        require(core.isEnabled()&&chronicle.isEnabled(),"Actual StarCore and Chronicle must be enabled");registry=call(call(core,"context"),"serviceRegistry");api=Objects.requireNonNull(getServer().getServicesManager().load(ChronicleService.class));
        Objects.requireNonNull(getCommand("ncverify")).setExecutor(this);log("READY",Map.of("product_sha256",expected,"seeded",getConfig().getBoolean("native-seeded",false),"noDatabaseAccess",true));
