    private static void require(boolean condition,String message){if(!condition)throw new IllegalStateException(message);}
    private void log(String kind,Object value){String line=SqliteStore.json(Map.of("time",Instant.now().toString(),"kind",kind,"value",value));getLogger().info("NATIONAL_"+kind+" "+SqliteStore.json(value));if(run!=null)synchronized(logLock){try{Files.writeString(run.resolve("evidence/national-fixture.jsonl"),line+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(Exception error){getLogger().severe("Evidence append failed: "+error);}}}
    private void failure(String operation,Throwable error){log("FAILED",Map.of("operation",operation,"error",error.toString()));error.printStackTrace();}
    private Player player(String who){require(CLIENTS.contains(who),"Unknown verification player");String name="PhaseTwo"+who;Player p=getServer().getPlayerExact(name);require(p!=null&&p.isOnline(),"Actual client must be connected: "+name);require(p.getUniqueId().equals(UUID.nameUUIDFromBytes(("OfflinePlayer:"+name).getBytes(StandardCharsets.UTF_8))),"Unexpected actual client UUID");require(!p.isOp(),"Acceptance clients must remain non-operators");return p;}
    private void grant(Player p){PermissionAttachment attachment=attachments.compute(p.getUniqueId(),(id,old)->old!=null&&old.getPermissible()==p?old:p.addAttachment(this));attachment.setPermission("starchronicle.use",true);attachment.setPermission("starchronicle.admin",false);attachment.setPermission("starcore.nation.ally.add",false);p.recalculatePermissions();p.setGameMode(GameMode.CREATIVE);require(p.hasPermission("starchronicle.use")&&!p.hasPermission("starchronicle.admin")&&!p.isOp(),"Non-admin native-client permission contract failed");}
    private Object nations()throws Exception {Class<?> type=Class.forName("dev.starcore.starcore.module.nation.NationService",true,core.getClass().getClassLoader());return ((Optional<?>)call(registry,"find",type)).orElseThrow();}
    private Optional<?> nationOf(Player p)throws Exception{return (Optional<?>)call(nations(),"nationOf",p.getUniqueId());}
    private Object nation(Player p)throws Exception{return nationOf(p).orElseThrow(()->new IllegalStateException("Actual player has no native nation"));}
    private Object nativeId(String value)throws Exception{return Class.forName("dev.starcore.starcore.module.nation.model.NationId",true,core.getClass().getClassLoader()).getMethod("fromString",String.class).invoke(null,value);}
    private String country(String label){String value=getConfig().getString("nations."+label,"");require(value.matches("[a-f0-9-]{36}"),"Native country has not been captured: "+label);return value;}
    private void identity(String who)throws Exception {Player p=player(who);Object service=nations();synchronized(service){Optional<?> n=nationOf(p);String id=n.isEmpty()?"":call(n.get(),"id").toString();boolean holder=n.isPresent()&&Boolean.TRUE.equals(call(service,"isFounder",p.getUniqueId(),call(n.get(),"id")));log("IDENTITY",Map.of("player",who,"uuid",p.getUniqueId(),"nation",id,"holder",holder,"op",p.isOp(),"use",p.hasPermission("starchronicle.use"),"admin",p.hasPermission("starchronicle.admin")));}}
    private void seed()throws Exception {
        for(String who:CLIENTS)grant(player(who));Object service=nations();
        if(!getConfig().getBoolean("native-seeded",false)){
            for(String who:List.of("A","B","C")){Player p=player(who);require(nationOf(p).isEmpty(),"Fresh run must not reuse another native membership");Object n=call(service,"createNation",p.getUniqueId(),p.getName(),"NationalCouncil"+who);Object id=call(n,"id");require(Boolean.TRUE.equals(call(service,"isFounder",p.getUniqueId(),id)),"Native createNation did not commit current ownership");require(call(nation(p),"id").equals(id),"Native membership was not committed");getConfig().set("nations."+who,id.toString());}
            Player d=player("D");require(nationOf(d).isEmpty(),"D must start as a real ordinary member");require(Boolean.TRUE.equals(call(service,"addMember",nativeId(country("A")),d.getUniqueId(),d.getName())),"Native addMember rejected D");require(!Boolean.TRUE.equals(call(service,"isFounder",d.getUniqueId(),nativeId(country("A")))),"Ordinary D must not be holder");getConfig().set("native-seeded",true);saveConfig();
        }
        for(String who:CLIENTS)identity(who);log("SEEDED",Map.of("actualPlayers",4,"capturedCountries",Map.of("A",country("A"),"B",country("B"),"C",country("C")),"createdThisBoot",!getConfig().getBoolean("seed-reported",false)));getConfig().set("seed-reported",true);saveConfig();
    }
    private static String story(String which){return switch(which){case "primary"->PRIMARY;case "invalidation"->INVALIDATION;default->throw new IllegalArgumentException("primary|invalidation");};}
    private CompletionStage<StoryInstance> instance(String which,UUID viewer){String story=story(which);return api.instances(viewer).thenApply(items->items.stream().filter(i->i.definition().id().equals(story)&&i.definition().version().equals("1")).findFirst().orElseThrow(()->new IllegalStateException("Actual test instance not yet active: "+story)));}
    private void begin(String which)throws Exception {
        String key="sources."+which;if(getConfig().contains(key+".time"))throw new IllegalStateException("Source already captured; use replay to submit its canonical stored value");
        Set<UUID> participants=new TreeSet<>();Set<String> countries=new TreeSet<>();for(String who:CLIENTS){Player p=player(who);participants.add(p.getUniqueId());countries.add(call(nation(p),"id").toString());}
        require(participants.size()==4&&countries.size()==3,"Signal must observe four actual clients and three distinct countries");String id="national-paper:"+which+":1",type=which.equals("primary")?"NATIONAL_PRIMARY_TEST":"NATIONAL_INVALIDATION_TEST";Instant time=Instant.now();
        getConfig().set(key+".time",time.toString());getConfig().set(key+".id",id);saveConfig();
        WorldEvent event=new WorldEvent(id,type,time,participants,countries,Map.of("fixture-only","true"),"NationalCouncilPaperFixture","Isolated acceptance signal, not a production discovery: actual connected client UUIDs and three country IDs observed through native NationService; signal="+which);
        log("SOURCE",event);api.submit(event).whenComplete((report,error)->{if(error!=null)failure("begin-"+which,error);else log("SUBMITTED",Map.of("story",story(which),"source",id,"duplicate",report.duplicate(),"instances",report.instanceIds()));});
    }
    private void state(String who,String which){UUID viewer=player(who).getUniqueId();instance(which,viewer).thenCompose(i->api.nationalState(i.id(),viewer)).whenComplete((value,error)->{if(error!=null)failure("state",error);else log("STATE",Map.of("player",who,"story",story(which),"state",value));});}
    private void vote(String who,String which,String choice,long revision,boolean reject){UUID actor=player(who).getUniqueId();instance(which,actor).thenCompose(i->api.nationalVote(i.id(),actor,"council",revision,choice)).whenComplete((value,error)->result("VOTE",who,which,revision,choice,reject,value,error));}
    private void withdraw(String who,String which,long revision,boolean reject){UUID actor=player(who).getUniqueId();instance(which,actor).thenCompose(i->api.withdrawNationalVote(i.id(),actor,"council",revision)).whenComplete((value,error)->result("WITHDRAW",who,which,revision,"",reject,value,error));}
    private void result(String action,String who,String which,long revision,String choice,boolean reject,Object value,Throwable error){if(reject){if(error==null)failure("expected-"+action+"-rejection",new IllegalStateException("Unexpected successful stale/unauthorized request"));else log("EXPECTED_REJECTION",Map.of("action",action,"player",who,"story",story(which),"revision",revision,"choice",choice,"error",error.toString()));}else if(error!=null)failure(action,error);else log(action,Map.of("player",who,"story",story(which),"revision",revision,"choice",choice,"report",value));}
    private void transfer(String from,String to)throws Exception {Player old=player(from),next=player(to);Object service=nations(),id=call(nation(old),"id");require(call(nation(next),"id").equals(id),"Successor must really be a native member");require(Boolean.TRUE.equals(call(service,"transferOwnership",id,old.getUniqueId(),next.getUniqueId(),next.getName())),"Native transferOwnership rejected");require(Boolean.TRUE.equals(call(service,"isFounder",next.getUniqueId(),id))&&!Boolean.TRUE.equals(call(service,"isFounder",old.getUniqueId(),id)),"Native ownership did not transfer");log("NATIVE_TRANSFER",Map.of("nation",id.toString(),"old",old.getUniqueId(),"new",next.getUniqueId()));identity(from);identity(to);}
    private void disband(String who)throws Exception {Player p=player(who);Object service=nations(),id=call(nation(p),"id");require(Boolean.TRUE.equals(call(service,"isFounder",p.getUniqueId(),id)),"Only actual current holder may disband in fixture");require(Boolean.TRUE.equals(call(service,"disbandNation",id,p.getUniqueId())),"Native disbandNation rejected");require(((Optional<?>)call(service,"nationById",id)).isEmpty(),"Native nation did not disappear");log("NATIVE_DISBAND",Map.of("nation",id.toString(),"actualActor",p.getUniqueId()));}
    private void move(String who,String host)throws Exception {Player p=player(who),target=player(host);Object service=nations(),id=call(nation(target),"id");require(Boolean.TRUE.equals(call(service,"leaveNation",p.getUniqueId())),"Native leaveNation rejected (a current holder must transfer first)");require(Boolean.TRUE.equals(call(service,"addMember",id,p.getUniqueId(),p.getName())),"Native addMember after departure rejected");require(call(nation(p),"id").equals(id),"Current native nationality differs after move");log("NATIVE_MOVE",Map.of("player",who,"nation",id.toString()));}
    private void replay(String which){String id=getConfig().getString("sources."+which+".id","");require(!id.isBlank(),"No captured source");api.history(null,null,0,100).thenCompose(events->{WorldEvent canonical=events.stream().filter(e->e.id().equals(id)).findFirst().orElseThrow();log("CANONICAL_REPLAY_SOURCE",canonical);return api.submit(canonical);}).whenComplete((report,error)->{if(error!=null)failure("replay",error);else if(!report.duplicate())failure("replay",new IllegalStateException("Canonical source was not deduplicated"));else log("REPLAY_DUPLICATE",Map.of("source",id,"report",report));});}
    private void facts(String who){UUID actor=player(who).getUniqueId();String suffix=PRIMARY+"/1/council";List<String> refs=List.of("past.player.choice."+suffix,"past.nation.choice."+suffix,"past.resolution.world."+suffix);api.recollections(actor,refs).whenComplete((value,error)->{if(error!=null)failure("facts",error);else log("FACTS",Map.of("player",who,"facts",value));});api.fate(actor).whenComplete((value,error)->{if(error!=null)failure("fate",error);else log("FATE",Map.of("player",who,"facts",value));});api.history(null,null,0,100).whenComplete((value,error)->{if(error!=null)failure("history",error);else log("HISTORY",value);});}
    private void checkPending(){UUID d=player("D").getUniqueId(),a=player("A").getUniqueId(),b=player("B").getUniqueId();instance("primary",d).thenCompose(i->api.nationalState(i.id(),d).thenCompose(ds->api.nationalState(i.id(),a).thenCompose(as->api.nationalState(i.id(),b).thenApply(bs->{require(!ds.completed()&&ds.representative()&&ds.canVote()&&ds.viewerRevision()==4,"D must retain true native representation and revision 4 after restart");require(!as.representative()&&!as.canVote(),"Former holder A cannot remain authorized");require(bs.viewerRevision()==2&&ds.counts().equals(Map.of("yes",1L)),"Restart changed national revision/counts");var withdrawn=bs.ballots().stream().filter(v->v.nationId().equals(bs.viewerNationId())).findFirst().orElseThrow();require(withdrawn.status().equals("WITHDRAWN")&&withdrawn.choiceId()==null,"Restart lost the national withdrawal tombstone");return Map.of("D",ds,"A",as,"B",bs);})))).whenComplete((value,error)->{if(error!=null)failure("check-pending",error);else log("PENDING_CHECK_PASS",value);});}
    private void checkFrozen(){UUID d=player("D").getUniqueId();String suffix=PRIMARY+"/1/council";instance("primary",d).thenCompose(i->api.nationalState(i.id(),d).thenCompose(state->api.recollections(d,List.of("past.player.choice."+suffix,"past.nation.choice."+suffix,"past.resolution.world."+suffix)).thenCompose(facts->api.fate(d).thenApply(fate->{require(state.completed()&&"yes".equals(state.resolution())&&state.counts().equals(Map.of("yes",2L,"no",1L)),"Frozen country result/counts differ");require("yes".equals(facts.get("past.nation.choice."+suffix))&&"yes".equals(facts.get("past.resolution.world."+suffix))&&!facts.containsKey("past.player.choice."+suffix),"National ballot was confused with personal or world facts");require("7".equals(fate.get("player.honor")),"Stable local reward must be exactly seven once");return Map.of("state",state,"facts",facts,"fate",fate);})))).whenComplete((value,error)->{if(error!=null)failure("check-frozen",error);else log("FROZEN_CHECK_PASS",value);});}
    private void checkInvalidated(){UUID c=player("C").getUniqueId();String hill=country("B");instance("invalidation",c).thenCompose(i->api.nationalState(i.id(),c)).thenApply(state->{var gone=state.ballots().stream().filter(v->v.nationId().equals(hill)).findFirst().orElseThrow();require(!state.completed()&&state.counts().equals(Map.of("yes",1L,"no",1L))&&gone.revision()==2&&gone.status().equals("INVALIDATED")&&gone.choiceId()==null,"Native-disbanded nation still counted or its audit tombstone was lost");return state;}).whenComplete((value,error)->{if(error!=null)failure("check-invalidated",error);else log("INVALIDATION_CHECK_PASS",value);});}
    @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(sender instanceof Player){sender.sendMessage("Isolated coordinator console fixture only");return true;}try{switch(args.length==0?"help":args[0]){
        case "seed"->seed();case "identity"->identity(args[1]);case "begin"->begin(args[1]);case "state"->state(args[1],args[2]);case "vote"->vote(args[1],args[2],args[3],Long.parseLong(args[4]),false);case "reject-vote"->vote(args[1],args[2],args[3],Long.parseLong(args[4]),true);
        case "withdraw"->withdraw(args[1],args[2],Long.parseLong(args[3]),false);case "reject-withdraw"->withdraw(args[1],args[2],Long.parseLong(args[3]),true);case "transfer"->transfer(args[1],args[2]);case "disband"->disband(args[1]);case "move"->move(args[1],args[2]);case "replay"->replay(args[1]);case "facts"->facts(args[1]);
        case "check-pending"->checkPending();case "check-frozen"->checkFrozen();case "check-invalidated"->checkInvalidated();case "phase"->log("PHASE",Map.of("label",String.join(" ",Arrays.copyOfRange(args,1,args.length))));default->log("HELP",Map.of("commands","seed | begin primary|invalidation | state A primary | vote A primary yes REV | reject-vote D primary yes REV | withdraw A primary REV | transfer A D | disband B | move A C | replay primary | facts D | check-pending | check-frozen | check-invalidated"));}
    }catch(Throwable error){failure(args.length==0?"command":args[0],error);}return true;}
    private static String digest(Path file)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(file)));}
    private static Object call(Object target,String name,Object...args)throws Exception{require(target!=null,"Missing native target: "+name);for(Method method:target.getClass().getMethods()){if(!method.getName().equals(name)||method.getParameterCount()!=args.length)continue;boolean fits=true;for(int i=0;i<args.length;i++)if(args[i]!=null&&!box(method.getParameterTypes()[i]).isInstance(args[i])){fits=false;break;}if(fits)return method.invoke(target,args);}throw new NoSuchMethodException(target.getClass().getName()+"."+name);}
    private static Class<?> box(Class<?> type){return type==boolean.class?Boolean.class:type==int.class?Integer.class:type==long.class?Long.class:type;}
